-- Nobita
-- Khong sua file nay. Moi thay doi lam hong bo giai ma.
local _ykbfky = 4
local _edyleg = 243
local _xmfozc = 230
local _cgcxpo = ""

local _fozeea = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _vetxzu(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _pgfdvx(d)
	d = d:gsub("[^" .. _fozeea .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_fozeea:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _mzyaex = _pgfdvx(_cgcxpo)
local _tdtqdl = { _ykbfky, _edyleg, _xmfozc }
local _qinirf = {}
for i = 1, #_mzyaex do
	_qinirf[i] = string.char(_vetxzu(_mzyaex:byte(i), _tdtqdl[(i - 1) % 3 + 1]))
end

local _fgdptr = load or loadstring
local _fcjhsp, _qlwksg = _fgdptr(table.concat(_qinirf), "=w")
if not _fcjhsp then
	gg.alert("File hong: " .. tostring(_qlwksg))
	os.exit()
end
_fcjhsp()
